import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int size = scanner.nextInt();
        scanner.nextLine();
        String str = scanner.nextLine().trim();
        char[] array = str.toCharArray();

        int[] values = new int[size];
        for (int i = 0; i < size; i++) {
            values[i] = scanner.nextInt();
        }
        scanner.nextLine();

        List<CharData> mismatchList = new ArrayList<>();
        List<CharData> dataList = new ArrayList<>();
        for (int i = 0; i < size / 2; i++) {
            if (values[i] > values[size - i - 1]) {
                swap(array, values, i);
            }
            CharData cd = new CharData(array[i], values[i], i);
            if (array[i] == array[size - i - 1]) {
                mismatchList.add(cd);
            }
            dataList.add(cd);
        }
        dataList.sort(Comparator.comparing(c -> c.value));

        int totalCost = 0;
        if (!isAntiPalindromic(array)) {
            if (mismatchList.size() == 1) {
                CharData wrongChar = mismatchList.get(0);
                for (CharData cd : dataList) {
                    if (cd.chr != wrongChar.chr && array[size - cd.idx - 1] != wrongChar.chr) {
                        totalCost = wrongChar.value + cd.value;
                        break;
                    }
                }
            } else if (mismatchList.size() > 1) {
                Map<Character, Integer> countMap = new HashMap<>();
                for (CharData cd : mismatchList) {
                    countMap.put(cd.chr, countMap.getOrDefault(cd.chr, 0) + 1);
                }
                int maxCount = Collections.max(countMap.values());
                List<CharData> appendList = new ArrayList<>();
                while (maxCount * 2 > mismatchList.size() + appendList.size()) {
                    char maxChar = Collections.max(countMap.entrySet(), Map.Entry.comparingByValue()).getKey();
                    for (CharData cd : dataList) {
                        if (cd.chr != maxChar && array[size - cd.idx - 1] != maxChar && !mismatchList.contains(cd) && !appendList.contains(cd)) {
                            appendList.add(cd);
                            break;
                        }
                    }
                }
                totalCost = mismatchList.stream().mapToInt(c -> c.value).sum() + appendList.stream().mapToInt(c -> c.value).sum();
            }
        }
        int sumValues = Arrays.stream(values).sum();
        System.out.println(sumValues - totalCost);
    }

    private static void swap(char[] arr, int[] vals, int i) {
        char tempChar = arr[i];
        arr[i] = arr[arr.length - i - 1];
        arr[arr.length - i - 1] = tempChar;

        int tempVal = vals[i];
        vals[i] = vals[vals.length - i - 1];
        vals[vals.length - i - 1] = tempVal;
    }

    private static boolean isAntiPalindromic(char[] arr) {
        int len = arr.length;
        for (int i = 0; i < len / 2; i++) {
            if (arr[i] == arr[len - i - 1]) {
                return false;
            }
        }
        return true;
    }

    static class CharData {
        char chr;
        int value;
        int idx;

        CharData(char chr, int value, int idx) {
            this.chr = chr;
            this.value = value;
            this.idx = idx;
        }
    }
}
