def swap(arr, vals, i):
    arr[i], arr[len(arr) - i - 1] = arr[len(arr) - i - 1], arr[i]
    vals[i], vals[len(vals) - i - 1] = vals[len(vals) - i - 1], vals[i]

def isAntiPalindromic(arr):
    length = len(arr)
    for i in range(length // 2):
        if arr[i] == arr[length - i - 1]:
            return False
    return True

